    wisp:{hp:50,sp:12,bo:6,lk:2,air:1,fw:3,wt:3}, brute:{hp:150,sp:6,bo:9,lk:3,air:0,fw:4,wt:3},
    splitter:{hp:90,sp:8,bo:6,lk:2,air:0,fw:6,wt:2}, mender:{hp:70,sp:8,bo:7,lk:2,air:0,fw:8,wt:1},
    splitling:{hp:0,sp:12,bo:1,lk:1,air:0,fw:99,wt:0} };
  const ORDER = ['grunt','runner','wisp','brute','splitter','mender'];
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  function posAt(r, p) {
    const pts = ROUTES[r]; let rem = p;
    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i], b = pts[i+1], len = Math.abs(b[0]-a[0]) + Math.abs(b[1]-a[1]);
